-- ============================================================
-- 00_base.sql  --  医疗评估与宣教系统 PostgreSQL 16 基础约定
-- ============================================================
-- 全库规范（所有 DDL 文件均遵守）：
--
--   主键:    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY
--   逻辑删除: deleted SMALLINT NOT NULL DEFAULT 0  (0=未删除, 1=已删除)
--   统一字段: creator VARCHAR(64)    NOT NULL DEFAULT ''
--             updator VARCHAR(64)    NOT NULL DEFAULT ''
--             create_time TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP
--             update_time TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP
--             deleted     SMALLINT    NOT NULL DEFAULT 0
--   外键:    不建物理外键，由业务层保证引用完整性
--   JSON:    快照/规则/可变结构使用 JSONB
--   数值:    金额/得分用 NUMERIC(x,y)；精度、次数用 INTEGER
--   时间:    TIMESTAMP(3)，业务层统一补充时区
--   字符集:  全库 UTF-8
--
-- 执行顺序（依次执行）：
--   00_base.sql
--   01_patient_task.sql
--   02_scale_template.sql
--   03_interaction.sql
--   04_assessment_exec.sql
--   05_quality_review.sql
--   06_content_delivery.sql
--   07a_education_template.sql
--   07b_education_run.sql
--   08a_consent_template.sql
--   08b_consent_run.sql
--   09_nursing_audit.sql
-- ============================================================

CREATE EXTENSION IF NOT EXISTS pgcrypto;   -- 用于加密字段与 UUID 生成
